  "tips": [
   "這組形容詞多以 -ful、-ive、-ous、-able 結尾，注意不要漏字或寫成 -full、-iveness。",
   "容易弄混的是描述感受的兩種尾綴：前者說自己被這樣困住，後者說會讓別人產生這種感覺，一次要記兩個。",
   "相反詞要成對背。安靜對吵鬧、勤勞對懶惰，練打字的時候順便把相反的那一個也打一次。"
  ]
