  "tips": [
   "加強語氣不要亂加：口語說「蠻好的」「還不錯」比較自然，正式場合才用「很棒」。",
   "三個音節以上的形容詞（例如重要的、困難的）不能加短尾巴，請一律用前面加字的那一種寫法。",
   "帶「很」的意思的加強語氣不要亂加：口語的幾個好、還不錯比較自然，正式場合才用很棒。"
  ]
