  "tips": [
   "時間用 at、地點大到國家用 in、小地方才用 on：at seven o'clock、in Taipei、on my birthday，三個位置不能互換。",
   "台灣中文常常省略介系詞，但英文名詞前面幾乎都要有：不要寫 I am student，要寫 I am a student。",
   "上、下、前、後的位置詞記固定搭配：above、below、behind、in front of，順序不能隨便調換。"
  ]
