  "tips": [
   "洗衣機、微波爐、數位相機這類複合詞，打字時兩個字都要完整打進去，中間不能漏。",
   "電器前面通常要有冠詞或所有詞，比如開電視、我的冰箱，少了冠詞句子就不對了。",
   "容易混的是電器本身和它的用法：電視用來看，燈用來開，練習時把搭配一起記最快。"
  ]
